use vstd::prelude::*;

verus! {
    fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
        requires
            a.len() > 0, // The input array must be non-empty
        ensures
            result.len() == a.len(), // The output array has the same length as the input
            (a.len() == 1 ==> result == a) // If the input length is 1, the result is identical to the input
            && (a.len() > 1 ==> result[0] == a[a.len() - 1] && result[a.len() - 1] == a[0]) // Swap first and last elements
            && (forall |i: usize| 1 <= i < a.len() - 1 ==> result[i] == a[i]), // Interior elements remain unchanged
    {
        let n = a.len();
        let mut result: Vec<i32> = vec![0; n]; // Initialize result with the same length as a

        if n == 1 {
            result[0] = a[0]; // If length is 1, copy the single element
        } else {
            result[0] = a[n - 1]; // Set the first element of result to the last element of a
            result[n - 1] = a[0]; // Set the last element of result to the first element of a

            // Copy the interior elements
            for i in 1..(n - 1)
                invariant
                    1 <= i <= n - 1, // i is within bounds
                    result.len() == a.len(), // Lengths are equal
                    result[0] == a[n - 1], // First element is set correctly
                    result[n - 1] == a[0], // Last element is set correctly
                    (forall |j: usize| 1 <= j < i ==> result[j] == a[j]), // All previous interior elements are copied correctly
                decreases n - 1 - i, // Decrease clause for the loop
            {
                result[i] = a[i]; // Copy the interior element
            }
        }
        result // Return the result
    }
}

